const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Define counties and border region
    const counties = ee.FeatureCollection('TIGER/2018/Counties');
    const craighead = counties.filter(ee.Filter.and(
      ee.Filter.eq('STATEFP', '05'),
      ee.Filter.eq('NAME', 'Craighead')
    ));
    const jackson = counties.filter(ee.Filter.and(
      ee.Filter.eq('STATEFP', '05'),
      ee.Filter.eq('NAME', 'Jackson')
    ));

    // Create border buffer (1km buffer around shared boundary)
    const border = craighead.geometry().intersection(jackson.geometry());
    const borderRegion = border.buffer(1000); // 1km buffer

    // 2. Function to get water extent for a date
    const getWaterExtent = function(targetDate) {
      const start = ee.Date(targetDate).advance(-1, 'day');
      const end = ee.Date(targetDate).advance(1, 'day');

      // Use Sentinel-1 for reliable water detection
      const s1 = ee.ImageCollection('COPERNICUS/S1_GRD')
        .filterBounds(borderRegion)
        .filterDate(start, end)
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
        .filter(ee.Filter.eq('instrumentMode', 'IW'))
        .sort('system:time_start');

      const size = s1.size().getInfo();
      if (size === 0) return {count: null, images: 0};

      // Take most recent image
      const image = ee.Image(s1.first());

      // Water detection using VH threshold (water typically < -20 dB)
      const vh = image.select('VH');
      const water = vh.lt(-20).rename('water');

      // Count water pixels in border region
      const stats = water.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: borderRegion,
        scale: 30,
        maxPixels: 1e9,
        bestEffort: true
      });

      const waterCount = ee.Number(stats.get('water')).getInfo();
      return {count: waterCount, images: size};
    };

    // 3. Get water extent for both dates
    console.log('Processing 2023-04-13...');
    const water2023 = getWaterExtent('2023-04-13');
    console.log(`2023 Images: ${water2023.images}, Water pixels: ${water2023.count}`);

    console.log('Processing 2025-04-13...');
    const water2025 = getWaterExtent('2025-04-13');
    console.log(`2025 Images: ${water2025.images}, Water pixels: ${water2025.count}`);

    // 4. Validate results
    if (water2023.images === 0 || water2025.images === 0) {
      console.log('<answer>C1</answer>');
      return;
    }

    if (water2023.count === null || water2025.count === null) {
      console.log('<answer>C3</answer>');
      return;
    }

    if (water2023.count === 0 && water2025.count === 0) {
      console.log('<answer>C2</answer>');
      return;
    }

    // 5. Compare water extent
    const greaterIn2025 = water2025.count > water2023.count;
    console.log(`2023 water pixels: ${water2023.count}`);
    console.log(`2025 water pixels: ${water2025.count}`);
    console.log(greaterIn2025 ? '<answer>A</answer>' : '<answer>B</answer>');

  } catch (error) {
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
